const SB = 'https://vchtdsfrryxnvceierkn.supabase.co';
const SB_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InZjaHRkc2Zycnl4bnZjZWllcmtuIiwicm9sZSI6ImFub24iLCJpYXQiOjE3Nzg0ODcyMTYsImV4cCI6MjA5NDA2MzIxNn0.VuPuPqCbVYlxNpeTulkKK-IMezzxg3C05c4kWn3evqo';
const SBH = { apikey: SB_KEY, Authorization: `Bearer ${SB_KEY}`, 'Content-Type': 'application/json' };

// 1. Load settings
const settings = await this.helpers.httpRequest({ url: `${SB}/rest/v1/settings?select=key,value&key=in.(claude_api_key,telegram_bot_token,telegram_owner_id)`, headers: SBH, json: true });
const S = Object.fromEntries(settings.map(s => [s.key, s.value]));

// 2. Existing prospects for dedupe
const existing = await this.helpers.httpRequest({ url: `${SB}/rest/v1/b2b_prospects?select=venue_name`, headers: SBH, json: true });
const norm = n => (n || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const known = new Set(existing.map(e => norm(e.venue_name)));

// 3. Claude with web search — find new venues
const prompt = `Search the web for NEWLY OPENED or SOON-TO-OPEN pickleball and padel court venues in Malaysia, specifically in: Klang Valley (KL/Selangor), Penang, and Johor (especially Johor Bahru). Focus on venues announced or opened in the last 6 months. Search Facebook, Instagram, news sites, Courtsite, AFA, Google Maps listings.\n\nFor each venue found, extract every contact detail you can find: phone/WhatsApp numbers, email, Instagram handle, Facebook page, website, booking platform link, address, owner or person-in-charge name.\n\nReturn ONLY a JSON array (no markdown, no commentary). Each element:\n{\"venue_name\":\"\",\"region\":\"Klang Valley|Penang|Johor\",\"city\":\"\",\"sport\":\"pickleball|padel|both\",\"status\":\"open|opening_soon\",\"opened_est\":\"YYYY-MM\",\"courts\":0,\"address\":\"\",\"phone\":\"\",\"whatsapp\":\"\",\"email\":\"\",\"instagram\":\"\",\"facebook\":\"\",\"website\":\"\",\"booking_link\":\"\",\"contact_person\":\"\",\"evidence_url\":\"\",\"notes\":\"\"}\nUse \"\" for unknown fields. Only include real venues you found evidence for — never invent.`;

const resp = await this.helpers.httpRequest({
  method: 'POST', url: 'https://api.anthropic.com/v1/messages',
  headers: { 'x-api-key': S.claude_api_key, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
  body: { model: 'claude-sonnet-4-6', max_tokens: 8000, tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: 10 }], messages: [{ role: 'user', content: prompt }] },
  json: true, timeout: 280000
});

const text = (resp.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
const m = text.match(/\[[\s\S]*\]/);
let venues = [];
try { venues = JSON.parse(m ? m[0] : '[]'); } catch (e) { venues = []; }

// 4. Insert new ones
const uid = () => Math.random().toString(36).slice(2, 9) + Date.now().toString(36).slice(-4);
const fresh = [];
for (const v of venues) {
  if (!v.venue_name || known.has(norm(v.venue_name))) continue;
  known.add(norm(v.venue_name));
  const row = {
    id: uid(), venue_name: v.venue_name, region: v.region || 'Klang Valley',
    stage: 'new', drip_step: 0, next_touch_at: new Date().toISOString(), source: 'ai_scout',
    data: { ...v, touches: [], detected_at: new Date().toISOString() },
    updated_at: new Date().toISOString()
  };
  try {
    await this.helpers.httpRequest({ method: 'POST', url: `${SB}/rest/v1/b2b_prospects`, headers: SBH, body: row, json: true });
    fresh.push(row);
  } catch (e) { /* unique index race — skip */ }
}

// 5. Telegram alert
if (S.telegram_bot_token && S.telegram_owner_id) {
  const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  let msg;
  if (fresh.length) {
    msg = `\uD83C\uDFAF <b>B2B Scout: ${fresh.length} new court lead${fresh.length > 1 ? 's' : ''} found!</b>\n\n` + fresh.map(r => `\uD83C\uDFD3 <b>${esc(r.venue_name)}</b> — ${esc(r.region)}\n${esc(r.data.city)} \u00B7 ${esc(r.data.sport)} \u00B7 ${esc(r.data.status)}${r.data.phone || r.data.whatsapp ? `\n\uD83D\uDCF1 ${esc(r.data.whatsapp || r.data.phone)}` : ''}${r.data.instagram ? `\n\uD83D\uDCF8 ${esc(r.data.instagram)}` : ''}`).join('\n\n') + `\n\n\u27A1\uFE0F Door Opener due now — open the B2B dashboard.`;
  } else {
    msg = `\uD83D\uDD0D B2B Scout ran — no new venues found today (${venues.length} checked, all already tracked).`;
  }
  await this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${S.telegram_bot_token}/sendMessage`, body: { chat_id: S.telegram_owner_id, text: msg.slice(0, 4000), parse_mode: 'HTML' }, json: true }).catch(() => {});
}

return [{ json: { checked: venues.length, inserted: fresh.length, names: fresh.map(f => f.venue_name) } }];
